// The program proves the package bytes against real Go: Buffer with each read
// and each write method, Reader, and each function of the package that the
// package strings also holds, with a byte slice in place of a string.
package main

import (
	"bytes"
	"fmt"
	"io"
	"slices"
	"unicode"
)

func row(label string, value any) {
	fmt.Printf("%-28s %v\n", label, value)
}

func rowq(label string, value []byte) {
	fmt.Printf("%-28s %q\n", label, value)
}

func rows(label string, value [][]byte) {
	fmt.Printf("%-28s %q\n", label, value)
}

func buffer() {
	var b bytes.Buffer
	row("zero Len", b.Len())
	row("zero Cap", b.Cap())
	rowq("zero Bytes", b.Bytes())
	row("zero String", fmt.Sprintf("%q", b.String()))
	n, err := b.WriteString("hello")
	row("WriteString", fmt.Sprint(n, " ", err))
	err = b.WriteByte(' ')
	row("WriteByte", err)
	n, err = b.WriteRune('世')
	row("WriteRune", fmt.Sprint(n, " ", err))
	n, err = b.WriteRune(-5)
	row("WriteRune invalid", fmt.Sprint(n, " ", err))
	n, err = b.Write([]byte("界!"))
	row("Write", fmt.Sprint(n, " ", err))
	rowq("Bytes", b.Bytes())
	row("Len", b.Len())
	row("Cap >= Len", b.Cap() >= b.Len())
	rowq("Next 3", b.Next(3))
	rowq("Next 100", b.Next(100))
	row("Len after Next", b.Len())
	b.WriteString("0123456789")
	p := make([]byte, 4)
	n, err = b.Read(p)
	row("Read", fmt.Sprintf("%d %v %q", n, err, p[:n]))
	c, err := b.ReadByte()
	row("ReadByte", fmt.Sprintf("%q %v", c, err))
	err = b.UnreadByte()
	row("UnreadByte", err)
	err = b.UnreadByte()
	row("UnreadByte twice", err)
	c, _ = b.ReadByte()
	row("ReadByte again", fmt.Sprintf("%q", c))
	b.WriteString("日本")
	r, size, err := b.ReadRune()
	row("ReadRune", fmt.Sprintf("%q %d %v", r, size, err))
	b.Truncate(3)
	rowq("Truncate 3", b.Bytes())
	r, size, err = b.ReadRune()
	row("ReadRune after Truncate", fmt.Sprintf("%q %d %v", r, size, err))
	err = b.UnreadRune()
	row("UnreadRune", err)
	r, size, _ = b.ReadRune()
	row("ReadRune again", fmt.Sprintf("%q %d", r, size))
	err = b.UnreadRune()
	err2 := b.UnreadRune()
	row("UnreadRune twice", fmt.Sprintf("%v / %v", err, err2))
	b.Reset()
	row("Reset Len", b.Len())
	b.WriteString("line one\nline two\nrest")
	line, err := b.ReadString('\n')
	row("ReadString", fmt.Sprintf("%q %v", line, err))
	bs, err := b.ReadBytes('\n')
	row("ReadBytes", fmt.Sprintf("%q %v", bs, err))
	line, err = b.ReadString('\n')
	row("ReadString at end", fmt.Sprintf("%q %v", line, err))
	line, err = b.ReadString('\n')
	row("ReadString of empty", fmt.Sprintf("%q %v", line, err))
	n, err = b.Read(p)
	row("Read of empty", fmt.Sprint(n, " ", err))
	n, err = b.Read(nil)
	row("Read into nil of empty", fmt.Sprint(n, " ", err))
	b.WriteString("x")
	n, err = b.Read(nil)
	row("Read into nil", fmt.Sprint(n, " ", err))
	_, err = b.ReadByte()
	_, err = b.ReadByte()
	row("ReadByte of empty", err)
	_, _, err = b.ReadRune()
	row("ReadRune of empty", err)
	b.Reset()
	b.Grow(64)
	row("Grow Cap >= 64", b.Cap() >= 64)
	row("Grow Len", b.Len())
	b.WriteString("abc")
	b.Truncate(0)
	row("Truncate 0 Len", b.Len())
	buf := b.AvailableBuffer()
	buf = append(buf, "avail"...)
	b.Write(buf)
	rowq("AvailableBuffer", b.Bytes())
	row("Available >= 0", b.Available() >= 0)
	b.Reset()
	m, err := b.ReadFrom(bytes.NewReader([]byte("from a reader")))
	row("ReadFrom", fmt.Sprint(m, " ", err))
	rowq("after ReadFrom", b.Bytes())
	var out bytes.Buffer
	m, err = b.WriteTo(&out)
	row("WriteTo", fmt.Sprint(m, " ", err))
	row("Len after WriteTo", b.Len())
	rowq("target", out.Bytes())
	m, err = b.WriteTo(&out)
	row("WriteTo of empty", fmt.Sprint(m, " ", err))
	made := bytes.NewBufferString("made")
	rowq("NewBufferString", made.Bytes())
	made2 := bytes.NewBuffer([]byte("buf"))
	rowq("NewBuffer", made2.Bytes())
	fmt.Fprintf(made2, " %d", 7)
	row("Fprintf", made2.String())
	var nilBuf *bytes.Buffer
	row("nil String", nilBuf.String())
	catch("Truncate out of range", func() { var b bytes.Buffer; b.WriteString("ab"); b.Truncate(5) })
	catch("Grow negative", func() { var b bytes.Buffer; b.Grow(-1) })
	big := bytes.Repeat([]byte("0123456789"), 100)
	var large bytes.Buffer
	for i := 0; i < 10; i++ {
		large.Write(big)
	}
	row("large Len", large.Len())
	head := large.Next(500)
	row("large Next", len(head))
	all, err := io.ReadAll(&large)
	row("large ReadAll", fmt.Sprint(len(all), " ", err))
	row("large Len after", large.Len())
	var rw io.ReadWriter = &b
	io.WriteString(rw, "via iface")
	row("as ReadWriter", b.String())
}

func catch(label string, f func()) {
	defer func() {
		r := recover()
		fmt.Printf("%-28s %v\n", label, r)
	}()
	f()
}

func reader() {
	r := bytes.NewReader([]byte("Hello, 世界! bye"))
	row("Len", r.Len())
	row("Size", r.Size())
	p := make([]byte, 5)
	n, err := r.Read(p)
	row("Read", fmt.Sprintf("%d %v %q", n, err, p[:n]))
	c, err := r.ReadByte()
	row("ReadByte", fmt.Sprintf("%q %v", c, err))
	row("UnreadByte", r.UnreadByte())
	r.ReadByte()
	r.ReadByte()
	ch, size, err := r.ReadRune()
	row("ReadRune", fmt.Sprintf("%q %d %v", ch, size, err))
	row("UnreadRune", r.UnreadRune())
	row("UnreadRune twice", r.UnreadRune())
	pos, err := r.Seek(-3, io.SeekEnd)
	row("Seek end", fmt.Sprint(pos, " ", err))
	rest, _ := io.ReadAll(r)
	row("rest", fmt.Sprintf("%q", rest))
	_, err = r.Seek(0, 9)
	row("Seek bad whence", err)
	_, err = r.Seek(-1, io.SeekStart)
	row("Seek negative", err)
	n, err = r.ReadAt(p, 7)
	row("ReadAt", fmt.Sprintf("%d %v %q", n, err, p[:n]))
	n, err = r.ReadAt(p, 100)
	row("ReadAt past end", fmt.Sprint(n, " ", err))
	n, err = r.ReadAt(p, -1)
	row("ReadAt negative", fmt.Sprint(n, " ", err))
	r.Reset([]byte("reset"))
	var sb bytes.Buffer
	m, err := r.WriteTo(&sb)
	row("WriteTo", fmt.Sprintf("%d %v %q", m, err, sb.Bytes()))
	row("Len after WriteTo", r.Len())
	_, err = r.ReadByte()
	row("ReadByte at end", err)
	row("UnreadByte at start", bytes.NewReader(nil).UnreadByte())
	n, err = bytes.NewReader(nil).Read(p)
	row("Read of nil", fmt.Sprint(n, " ", err))
}

func functions() {
	s := []byte("chicken and chips and dips")
	row("Compare less", bytes.Compare([]byte("a"), []byte("b")))
	row("Compare equal", bytes.Compare([]byte("a"), []byte("a")))
	row("Compare nil and empty", bytes.Compare(nil, []byte{}))
	row("Compare prefix", bytes.Compare([]byte("ab"), []byte("abc")))
	row("Equal", bytes.Equal([]byte("ab"), []byte("ab")))
	row("Equal nil and empty", bytes.Equal(nil, []byte{}))
	row("Equal differ", bytes.Equal([]byte("ab"), []byte("ac")))
	row("EqualFold", bytes.EqualFold([]byte("Go"), []byte("GO")))
	row("EqualFold kelvin", bytes.EqualFold([]byte("K"), []byte("k")))
	row("Index", bytes.Index(s, []byte("and")))
	row("Index empty", bytes.Index(s, nil))
	row("Index absent", bytes.Index(s, []byte("beef")))
	row("LastIndex", bytes.LastIndex(s, []byte("and")))
	row("IndexByte", bytes.IndexByte(s, 'k'))
	row("LastIndexByte", bytes.LastIndexByte(s, 'd'))
	row("IndexRune", bytes.IndexRune([]byte("chicken 日本"), '本'))
	row("IndexRune invalid", bytes.IndexRune([]byte("a\xffb"), unicode.ReplacementChar))
	row("IndexAny", bytes.IndexAny(s, "pd"))
	row("LastIndexAny", bytes.LastIndexAny(s, "ck"))
	row("IndexFunc", bytes.IndexFunc([]byte("abc123"), unicode.IsDigit))
	row("LastIndexFunc", bytes.LastIndexFunc([]byte("a1b2c"), unicode.IsDigit))
	row("Contains", bytes.Contains(s, []byte("chips")))
	row("ContainsAny", bytes.ContainsAny(s, "xyzk"))
	row("ContainsRune", bytes.ContainsRune([]byte("日本語"), '本'))
	row("ContainsFunc", bytes.ContainsFunc([]byte("abc"), unicode.IsUpper))
	row("HasPrefix", bytes.HasPrefix(s, []byte("chick")))
	row("HasSuffix", bytes.HasSuffix(s, []byte("dips")))
	row("Count", bytes.Count(s, []byte("and")))
	row("Count of empty", bytes.Count([]byte("five"), nil))
	row("Count overlap", bytes.Count([]byte("aaaa"), []byte("aa")))
	rows("Fields", bytes.Fields([]byte("  foo bar  baz   ")))
	rows("Fields unicode", bytes.Fields([]byte("a\u00a0b\u3000c")))
	row("Fields empty", len(bytes.Fields([]byte("  "))))
	rows("FieldsFunc", bytes.FieldsFunc([]byte("a1b22c333"), unicode.IsDigit))
	rows("Split", bytes.Split([]byte("a,b,,c"), []byte(",")))
	rows("Split empty sep", bytes.Split([]byte("日本"), nil))
	rows("SplitN 2", bytes.SplitN([]byte("a,b,c"), []byte(","), 2))
	row("SplitN 0", bytes.SplitN([]byte("a,b"), []byte(","), 0) == nil)
	rows("SplitAfter", bytes.SplitAfter([]byte("a,b,c"), []byte(",")))
	rows("SplitAfterN 2", bytes.SplitAfterN([]byte("a,b,c"), []byte(","), 2))
	rowq("Join", bytes.Join([][]byte{[]byte("a"), []byte("b")}, []byte("-")))
	rowq("Join none", bytes.Join(nil, []byte("-")))
	before, after, found := bytes.Cut([]byte("k=v=w"), []byte("="))
	row("Cut", fmt.Sprintf("%q %q %v", before, after, found))
	before, after, found = bytes.Cut([]byte("kv"), []byte("="))
	row("Cut absent", fmt.Sprintf("%q %q %v", before, after, found))
	before, after, found = bytes.CutLast([]byte("k=v=w"), []byte("="))
	row("CutLast", fmt.Sprintf("%q %q %v", before, after, found))
	after, found = bytes.CutPrefix([]byte("prefix-body"), []byte("prefix-"))
	row("CutPrefix", fmt.Sprintf("%q %v", after, found))
	before, found = bytes.CutSuffix([]byte("body.txt"), []byte(".txt"))
	row("CutSuffix", fmt.Sprintf("%q %v", before, found))
	rowq("Trim", bytes.Trim([]byte("xxhixyx"), "xy"))
	rowq("Trim rune", bytes.Trim([]byte("本日"), "日"))
	rowq("TrimLeft", bytes.TrimLeft([]byte("xxhixx"), "x"))
	rowq("TrimRight", bytes.TrimRight([]byte("xxhixx"), "x"))
	rowq("TrimSpace", bytes.TrimSpace([]byte(" \t hi \n")))
	rowq("TrimSpace unicode", bytes.TrimSpace([]byte("\u00a0hi\u0085")))
	rowq("TrimSpace all", bytes.TrimSpace([]byte("   ")))
	rowq("TrimPrefix", bytes.TrimPrefix([]byte("prefix-body"), []byte("prefix-")))
	rowq("TrimSuffix", bytes.TrimSuffix([]byte("body.txt"), []byte(".txt")))
	rowq("TrimFunc", bytes.TrimFunc([]byte("123abc456"), unicode.IsDigit))
	rowq("TrimLeftFunc", bytes.TrimLeftFunc([]byte("123abc456"), unicode.IsDigit))
	rowq("TrimRightFunc", bytes.TrimRightFunc([]byte("123abc456"), unicode.IsDigit))
	rowq("ToUpper", bytes.ToUpper([]byte("Hello, ß ǅ ſ")))
	rowq("ToLower", bytes.ToLower([]byte("Hello, İ K Σ")))
	rowq("ToTitle", bytes.ToTitle([]byte("hello ǆ")))
	rowq("ToUpperSpecial", bytes.ToUpperSpecial(unicode.TurkishCase, []byte("iı")))
	rowq("ToLowerSpecial", bytes.ToLowerSpecial(unicode.TurkishCase, []byte("İI")))
	rowq("ToTitleSpecial", bytes.ToTitleSpecial(unicode.TurkishCase, []byte("i")))
	rowq("Title", bytes.Title([]byte("hello wORLD o'neil")))
	rowq("ToValidUTF8", bytes.ToValidUTF8([]byte("a\xffb\xfe\xfdc"), []byte("?")))
	rowq("Map", bytes.Map(func(r rune) rune {
		if r == 'x' {
			return -1
		}
		return unicode.ToUpper(r)
	}, []byte("axbxc 日")))
	rowq("Map invalid", bytes.Map(func(r rune) rune { return r }, []byte("a\xffb")))
	rowq("Repeat", bytes.Repeat([]byte("ab"), 3))
	rowq("Repeat 0", bytes.Repeat([]byte("ab"), 0))
	rowq("Replace", bytes.Replace([]byte("oink oink oink"), []byte("k"), []byte("ky"), 2))
	rowq("Replace empty old", bytes.Replace([]byte("abc"), nil, []byte("-"), -1))
	rowq("ReplaceAll", bytes.ReplaceAll([]byte("a.b.c"), []byte("."), []byte("::")))
	row("Runes", bytes.Runes([]byte("a日\xff")))
	rowq("Clone", bytes.Clone([]byte("clone")))
	row("Clone nil", bytes.Clone(nil) == nil)
	row("Clone empty", bytes.Clone([]byte{}) == nil)
	rows("Lines", slices.Collect(bytes.Lines([]byte("a\nb\n\nc"))))
	rows("SplitSeq", slices.Collect(bytes.SplitSeq([]byte("a,b,,c"), []byte(","))))
	rows("SplitAfterSeq", slices.Collect(bytes.SplitAfterSeq([]byte("a,b,c"), []byte(","))))
	rows("FieldsSeq", slices.Collect(bytes.FieldsSeq([]byte("  a  b\tc\n"))))
	rows("FieldsFuncSeq", slices.Collect(bytes.FieldsFuncSeq([]byte("a1b2c"), unicode.IsDigit)))
	row("MinRead", bytes.MinRead)
	row("ErrTooLarge", bytes.ErrTooLarge)
}

// aliasing proves that a function of the package shares the array of its
// argument where Go shares it, and copies where Go copies.
func aliasing() {
	src := []byte("hello world")
	trimmed := bytes.TrimSpace(src)
	trimmed[0] = 'J'
	row("TrimSpace shares", string(src))
	fields := bytes.Fields(src)
	fields[1][0] = 'W'
	row("Fields shares", string(src))
	up := bytes.ToUpper(src)
	up[0] = 'x'
	row("ToUpper copies", string(src))
	parts := bytes.Split(src, []byte(" "))
	parts[0][1] = 'E'
	row("Split shares", string(src))
	var b bytes.Buffer
	b.WriteString("buffer")
	view := b.Bytes()
	view[0] = 'B'
	row("Bytes shares", b.String())
	next := b.Next(3)
	next[0] = 'b'
	row("Next shares", string(view))
	b.WriteString("XYZ")
	row("String after write", b.String())
}

func main() {
	fmt.Println("== Buffer ==")
	buffer()
	fmt.Println("== Reader ==")
	reader()
	fmt.Println("== the functions ==")
	functions()
	fmt.Println("== the aliasing ==")
	aliasing()
}
